import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:slotbookingadmin/core/api/api_services.dart'; import 'package:slotbookingadmin/core/api/session_manager.dart';
enum AppRole{user,admin,superadmin} class LoginState{final bool loading;final String? error;final AppRole? selectedRole;LoginState({this.loading=false,this.error,this.selectedRole});LoginState copyWith({bool? loading,String? error,AppRole? selectedRole})=>LoginState(loading:loading??this.loading,error:error,selectedRole:selectedRole??this.selectedRole);}
final loginNotifierProvider=StateNotifierProvider<LoginNotifier,LoginState>((ref)=>LoginNotifier()); class LoginNotifier extends StateNotifier<LoginState>{LoginNotifier():super(LoginState());final _auth=AuthApi();void selectRole(AppRole r)=>state=state.copyWith(selectedRole:r,error:null);String roleToString(AppRole r)=>r==AppRole.admin?'admin':r==AppRole.superadmin?'superadmin':'user';AppRole stringToRole(String r)=>r=='admin'?AppRole.admin:r=='superadmin'?AppRole.superadmin:AppRole.user;Future<AppRole?> getCurrentUserRole()async=>SessionManager.currentRole==null?null:stringToRole(SessionManager.currentRole!); Future<void> login({required String email,required String password,required AppRole role})async{try{state=state.copyWith(loading:true,error:null);final d=await _auth.login(email.trim(),password.trim());final dbRole=(d['role']??(d['user'] is Map?d['user']['role']:null)??SessionManager.currentRole??'user').toString();if(dbRole!=roleToString(role)){await _auth.logout();throw Exception('Invalid role selected');}state=state.copyWith(loading:false);}catch(e){state=state.copyWith(loading:false,error:e.toString().replaceAll('Exception:','').trim());}} Future<void> register({required String name,required String email,required String phone,required String password,required AppRole role})async{try{state=state.copyWith(loading:true,error:null);await _auth.register(name:name,email:email,phone:phone,password:password,role:roleToString(role));state=state.copyWith(loading:false);}catch(e){state=state.copyWith(loading:false,error:e.toString().replaceAll('Exception:','').trim());}}Future<void> logout()=>_auth.logout();Future<void> sendOtp({required String phoneNumber,required Function(String) onCodeSent,required Function(String) onError})async=>onError('Phone OTP is not available in the current API.');Future<void> verifyOtp({required String verificationId,required String otp})async=>state=state.copyWith(loading:false,error:'Phone OTP is not available in the current API.');}
